/* CPF Jurong Building, OSM way 103752945. Original geometry in local metres.
 * Green/white curved frontage, square/round ornamental bays and arched portals.
 * Height is fitted to the image-only reference when available; see REVIEW.md.
 */
{
const {register,scale,out,lerp,rect}=SGJE;
// Own measured registration height; shared catalogue is regenerated by the lead.
SGJE.data.cpf_jurong.height=22.5;
SGJE.data.cpf_jurong.height_source='Measured roof-minus-ground (image-only reference metadata)';
register('cpf_jurong','裕廊公积金大厦','CPF Jurong Building',42,(b,D)=>{
 const P=D.parts[0].p,H=20;
 const court=[[-13,-8],[-5,-8],[5,-4],[12,3],[8,7],[6,12],[-10,15],[-14,6]];
 b.walls(P,-.4,H-.45,'#e2e6de');
 b.walls(out(P,.035),.25,13.7,'#327569');
 b.band(out(P,.10),13.65,.45,'#edf0e7');
 b.band(out(P,.16),H-.55,.34,'#a8b5af');b.capHole(P,[court],H-.18,'#a5afa5');b.cap(court,H-4.5,'#8a9791');b.walls(court,H-4.5,H-.18,'#bac8bf');
 const Q=out(P,.12);
 function face(i){const p=Q[i],q=Q[(i+1)%P.length],dx=q[0]-p[0],dz=q[1]-p[1],L=Math.hypot(dx,dz);return {p,q,L,at:(t,y,off=0)=>[p[0]+dx*t-dz/L*off,y,p[1]+dz*t+dx/L*off]};}
 function panel(F,t,w,lo,hi,c,mode=0,off=.02){const d=w/F.L/2;b.quad(c,F.at(t-d,lo,off),F.at(t+d,lo,off),F.at(t+d,hi,off),F.at(t-d,hi,off),mode);}
 function frame(F,t,w,lo,hi,c='#eef0e7',th=.15,off=.07){const d=w/F.L/2;for(const [a,v]of [[lo,lo+th],[hi-th,hi]])panel(F,t,w,a,v,c,0,off);for(const s of [-1,1])panel(F,t+s*(w-th)/2/F.L,th,lo,hi,c,0,off);}
 function circle(F,t,y,r,c,th=.10,off=.10){for(let k=0;k<24;k++){const a=k/24*Math.PI*2,v=(k+1)/24*Math.PI*2;b.quad(c,F.at(t+Math.cos(a)*r/F.L,y+Math.sin(a)*r,off),F.at(t+Math.cos(v)*r/F.L,y+Math.sin(v)*r,off),F.at(t+Math.cos(v)*(r-th)/F.L,y+Math.sin(v)*(r-th),off),F.at(t+Math.cos(a)*(r-th)/F.L,y+Math.sin(a)*(r-th),off));}}
 for(let i=0;i<P.length;i++){
  const F=face(i),front=i>=8||i===0,n=Math.max(1,Math.round(F.L/(front?5.3:5.7)));
  // Fine horizontal joints in the green rendered panels.
  for(let y=.75;y<13.6;y+=.48)b.beam(F.at(0,y,.015),F.at(1,y,.015),.025,'#50877a');
  for(let k=0;k<n;k++){
   const t=(k+.5)/n,w=Math.min(3.25,F.L/n-.55);
   for(const [lo,hi]of [[9.65,13.1],[15,18.35]]){
    panel(F,t,w,lo,hi,'#28575d',2);frame(F,t,w+.34,lo-.17,hi+.17);
    panel(F,t,.07,lo,hi,'#879f9c',0,.08);panel(F,t,w,lo+1.2,lo+1.29,'#8caba7',0,.08);
   }
   if(front&&w>2){
    panel(F,t,w,.3,4.25,'#355d5b',2);frame(F,t,w+.35,.25,4.45,'#e9eae1',.20);
    panel(F,t,w+.35,4.1,5.25,'#e4e8dc');
    panel(F,t,w,5.4,8.4,'#286158',2);frame(F,t,w+.38,5.25,8.65,'#eef0e8',.16);
    frame(F,t,w-.18,5.55,8.35,'#e6ebe1',.08,.11);circle(F,t,6.95,1.13,'#eff0e7',.14);
   }else{
    panel(F,t,w,.9,3.9,'#315859',2);frame(F,t,w,.9,3.9,'#c5d4c9',.10);
    panel(F,t,w,5.6,8.2,'#3d6564',2);frame(F,t,w,5.6,8.2,'#c5d4c9',.10);
   }
  }
 }
 // Large end portal on the east return: inset glass semicircle and white arch.
 const F=face(8),t=.5,w=Math.min(5.8,F.L-.5),r=w/2;
 panel(F,t,w,.25,6.0,'#31585d',2,.15);panel(F,t,w,3.3,4.6,'#eceee4',0,.21);
 for(let k=0;k<24;k++){const a=k/24*Math.PI,v=(k+1)/24*Math.PI;b.tri('#31585d',F.at(t,6,.15),F.at(t+Math.cos(a)*r/F.L,6+Math.sin(a)*r,.15),F.at(t+Math.cos(v)*r/F.L,6+Math.sin(v)*r,.15),2);b.quad('#f0f1e8',F.at(t+Math.cos(a)*(r+.28)/F.L,6+Math.sin(a)*(r+.28),.22),F.at(t+Math.cos(v)*(r+.28)/F.L,6+Math.sin(v)*(r+.28),.22),F.at(t+Math.cos(v)*r/F.L,6+Math.sin(v)*r,.22),F.at(t+Math.cos(a)*r/F.L,6+Math.sin(a)*r,.22));}
 frame(F,t,w+.5,.25,6.0,'#edf0e6',.25,.22);
 // Recessed crescent roof deck, curved inner parapet and rear service core.
 // The outer green/white facade remains the unmodified OSM building edge.
 const inner=scale(P,.62,[-8,9]);
 for(let i=8;i<P.length;i++){
  const a=inner[i],q=inner[(i+1)%P.length];
  b.beam([a[0],H+5.0,a[1]],[q[0],H+5.0,q[1]],.24,'#e3e7dc');
  b.quad('#d7dfd6',[a[0],H-.1,a[1]],[q[0],H-.1,q[1]],[q[0],H+5.0,q[1]],[a[0],H+5.0,a[1]]);
 }
 const R=rect(-14,-5,16,13,-.17);b.prism(R,H-.18,H+5.6,'#e2e7df');b.cap(R,H+5.65,'#a2aea5');b.rim(R,22.5/.87-.1,'#e7ebe3',.2);
 b.facade(out(R,.04),H+1.2,H+4.3,3,3.1,'#547272','#dce3da',0);
 for(const x of [-5,0,5]){b.box(x,H-4.4,9,3.4,1.05,6,'#b9c3bd',-.17);for(let k=-1;k<=1;k++)b.box(x+k*.85,H-3.34,9,.65,.05,5.2,'#566969',-.17);}
 b.rim(scale(P,.985),H-.03,'#e1e6dc',.22);
 // Blank facade panel in place of lettering. No logos or tenant graphics.
 panel(face(13),.5,7.1,18.7,19.15,'#dbe5dc',0,.04);
 // Authored facade levels normalised to measured median roof17.4m; the
 // independent rear parapet reaches the measured maximum22.5m.
 for(const bucket of b.buckets.values())for(let i=1;i<bucket.p.length;i+=3)bucket.p[i]=b.base+(bucket.p[i]-b.base)*.87;
});
}
